#include "stdafx.h"#include "Variable.h"#ifdef _DEBUG#define new DEBUG_NEW#undef THIS_FILEstatic char THIS_FILE[] = __FILE__;#endifusing namespace std;KAnalogVariable::KAnalogVariable(){}KAnalogVariable::KAnalogVariable( LPCSTR pUnits, int num ){}KAnalogVariable::KAnalogVariable( std::vector<std::string> &params ){  m_Number = atoi( params.at(4).c_str() );  ASSD( params.at(6).at(0)=='R' );  for( size_t i=0; i<params.size(); i++ )  {    if( !params.at(i).compare("Analog") )    {      m_DecPics = atoi( params.at(i-1).c_str() );      string t = params.at(i-2);      if( t.at(0)!='R' )        m_szEU = t;    }  }}//////////////////////////////////////////////////////////////////////////KDigitalVariable::KDigitalVariable(){}KDigitalVariable::KDigitalVariable( std::vector<std::string> &params ){  m_Number = atoi( params.at(4).c_str() );  ASSD( params.at(6).at(0)=='R' );  for( size_t i=0; i<params.size(); i++ )  {    if( !params.at(i).compare("Digital") )    {      m_DecPics = atoi( params.at(i-1).c_str() );      string t = params.at(i-2);      if( t.at(0)!='R' )        m_szEU = t;    }  }}